 'use strict';
const assert=require('node:assert/strict'),util=require('node:util'),crypto=require('node:crypto');
assert.equal(process.version,'v26.13.0');const phase=process.argv[2]||'after';
const nativeKeys=require('internal/crypto/keys');const fixture=phase==='native'?null:require('./key-platform.cjs').create();
const keys=phase==='native'?nativeKeys:fixture.privateKeys,api=phase==='native'?crypto:fixture;
const web=phase==='native'?require('internal/crypto/webidl'):fixture.cryptoWebIDL,rows=[];
function error(fn){try{fn();return{threw:false};}catch(e){return{name:e.name,code:e.code,message:e.message};}}
function group(name,fn){try{rows.push({name,pass:true,value:fn()});}catch(e){rows.push({name,pass:false,error:{name:e.name,code:e.code,message:e.message}});}}
group('complete converter shape and AlgorithmIdentifier union',()=>{assert(web);const c=web.converters,obj={get name(){throw Error('union must not read name');}};assert.equal(c.AlgorithmIdentifier(obj),obj);const symbol=error(()=>c.AlgorithmIdentifier(Symbol('algorithm')));assert.equal(symbol.name,'TypeError');return{converterKeys:Object.keys(c).sort(),algorithmKeys:Object.keys(web.algorithmConverters).sort(),validatorKeys:Object.keys(web.validators).sort(),nullPrototypes:[c,web.algorithmConverters,web.validators].map(v=>Object.getPrototypeOf(v)===null),sameObject:c.AlgorithmIdentifier(obj)===obj,symbol};});
group('inherited dictionary getters preserve order and abrupt identity',()=>{const trace=[],parent={get name(){trace.push('name');return'AES-CBC';}},v=Object.create(parent);Object.defineProperty(v,'iv',{get(){trace.push('iv');return Uint8Array.of(...Array(16).fill(0));}});const out=web.converters.AesCbcParams(v);assert.equal(out.name,'AES-CBC');const reason={original:true};let same=false;try{web.converters.Algorithm({get name(){throw reason;}});}catch(e){same=e===reason;}assert(same);return{trace,keys:Object.keys(out),ivLength:out.iv.byteLength,sameOriginal:same};});
group('KeyUsage sequence validates genuine iterator in order',()=>{const trace=[],v={get[Symbol.iterator](){trace.push('iterator');return function(){let i=0;return{next(){trace.push('next:'+i);return i++<2?{done:false,value:'deriveBits'}:{done:true};}};}}};const out=web.converters['sequence<KeyUsage>'](v);assert.deepEqual(out,['deriveBits','deriveBits']);const bad=error(()=>web.converters['sequence<KeyUsage>'](['deriveBits','not-usage']));assert.equal(bad.name,'TypeError');return{trace,out,bad};});
group('BufferSource uses real view brand and intrinsic backing range',()=>{const bytes=Uint8Array.from([9,...Array(16).fill(3),8]),view=bytes.subarray(1,17);let hooks=0;for(const key of ['buffer','byteOffset','byteLength'])Object.defineProperty(view,key,{get(){hooks++;throw Error('mutable '+key);}});view.valueOf=()=>{hooks++;throw Error('valueOf');};view[Symbol.iterator]=()=>{hooks++;throw Error('iterator');};const out=web.converters.AesCbcParams({name:'AES-CBC',iv:view});assert.equal(out.iv,view);web.validators.AesCbcParams(out);const dv=new DataView(bytes.buffer,1,16);for(const key of ['buffer','byteOffset','byteLength'])Object.defineProperty(dv,key,{get(){hooks++;throw Error('mutable DataView '+key);}});const dvOut=web.converters.AesCbcParams({name:'AES-CBC',iv:dv});web.validators.AesCbcParams(dvOut);assert.equal(dvOut.iv,dv);const rab=new ArrayBuffer(20,{maxByteLength:32}),resizable=new Uint8Array(rab,2,16);const resized=web.converters.AesCbcParams({name:'AES-CBC',iv:resizable});web.validators.AesCbcParams(resized);rab.resize(32);web.validators.AesCbcParams(resized);assert.equal(resized.iv,resizable);assert.equal(hooks,0);const shared=error(()=>web.converters.BufferSource(new Uint8Array(new SharedArrayBuffer(16))));const proxy=error(()=>web.converters.BufferSource(new Proxy(Uint8Array.of(1),{})));const detached=new ArrayBuffer(16);structuredClone(detached,{transfer:[detached]});const det=error(()=>web.validators.AesCbcParams(web.converters.AesCbcParams({name:'AES-CBC',iv:detached})));return{sameView:out.iv===view,sameDataView:dvOut.iv===dv,resizableSame:resized.iv===resizable,hooks,shared,proxy,detached:det};});
group('algorithm conversion and operation validation remain separate',()=>{const v={name:'AES-CTR',counter:new Uint8Array(16),length:0};const converted=web.algorithmConverters.AesCtrParams(v);assert.equal(converted.length,0);const later=error(()=>web.validators.AesCtrParams(converted));const direct=error(()=>web.converters.AesCtrParams(v));const validatedDirect=error(()=>web.validators.AesCtrParams(web.converters.AesCtrParams(v)));const rsaRange=error(()=>web.converters.RsaKeyGenParams({name:'RSA-PSS',modulusLength:Infinity,publicExponent:Uint8Array.of(1,0,1)}));const enforce=error(()=>web.converters.AesKeyGenParams({name:'AES-CBC',length:Infinity}));assert.equal(later.name,'OperationError');assert.deepEqual(direct,{threw:false});assert.deepEqual(validatedDirect,later);assert.equal(rsaRange.name,'TypeError');assert.equal(enforce.name,'TypeError');return{keys:Object.keys(converted),length:converted.length,later,direct,validatedDirect,rsaRange,enforce};});
group('pure byte-limit KMAC and digest-inventory validation are real',()=>{const max=error(()=>web.validators.HkdfParams(web.converters.HkdfParams({name:'HKDF',hash:'SHA-256',salt:new Uint8Array(),info:new Uint8Array(1025)})));const kmac=error(()=>web.validators.KmacImportParams(web.converters.KmacImportParams({name:'KMAC128',length:31})));const saved=crypto.getHashes;let publicCalls=0,cshake;try{crypto.getHashes=()=>{publicCalls++;throw Error('mutable public digest inventory');};cshake=error(()=>web.validators.CShakeParams(web.converters.CShakeParams({name:'not-a-native-digest',outputLength:8,customization:Uint8Array.of(1)})));}finally{crypto.getHashes=saved;}assert.equal(publicCalls,0);assert.equal(max.name,'OperationError');assert.equal(kmac.name,'NotSupportedError');assert.equal(cshake.name,'NotSupportedError');return{max,kmac,cshake,publicCalls};});
group('CryptoKey converter consumes genuine private native brand',()=>{const key=keys.importGenericSecretKey({name:'HKDF'},'raw',Uint8Array.of(1,2,3),false,['deriveBits']);assert.equal(web.converters.CryptoKey(key),key);let hooks=0;const fake={get type(){hooks++;throw Error('public type must not brand');}};const denied=error(()=>web.converters.CryptoKey(fake));assert.equal(denied.name,'TypeError');assert.equal(hooks,0);return{real:true,denied,hooks};});
group('public toCryptoKey reaches real WebIDL before receiver or normalization',()=>{const key=api.createSecretKey(Uint8Array.of(1,2,3));const wrongSymbol=error(()=>key.toCryptoKey(Symbol('x'),false,['deriveBits']));const borrowedSymbol=error(()=>Reflect.apply(api.KeyObject.prototype.toCryptoKey,{},[Symbol('x'),false,['deriveBits']]));assert.equal(wrongSymbol.name,'TypeError');assert.deepEqual(borrowedSymbol,wrongSymbol);return{wrongSymbol,borrowedSymbol};});
// These are explicit remaining divergences, never passing converter coverage.
const frontiers={validPublicImport:error(()=>api.createSecretKey(Uint8Array.of(1,2,3)).toCryptoKey('HKDF',false,['deriveBits'])),fipsDependentValidator:error(()=>web?.validators.RsaKeyGenParams(web.converters.RsaKeyGenParams({name:'RSA-PSS',modulusLength:2048,publicExponent:Uint8Array.of(1,0,1)})))};
console.log(JSON.stringify({phase,pass:rows.filter(r=>r.pass).length,fail:rows.filter(r=>!r.pass).length,rows,frontiers,scope:'Complete pinned crypto WebIDL production factory and existing generic WebIDL source over actual native key handle/Buffer/Values/types/digest dependencies; no guest/provider/FIPS/normalizer/Subtle/public-key-import/four-host claim.'}));if(rows.some(r=>!r.pass))process.exitCode=1;
